QURANIC_PHRASES.extend([
    # Additional famous Quranic Ayahs & Du'as
    ("وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ", "وإذا سألك عبادي عني فإني قريب", ["wa idha sa2alaka 3ibadee 3annee fa-innee qareeb", "wa idha sa'alaka 3ibadi 3anni fa inni qarib"], "And when My servants ask you concerning Me - indeed I am near"),
    ("أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ", "أجيب دعوة الداع إذا دعان", ["ujeebu da3wata al-da3i idha da3an", "ujibu da3watad-da3i idha da3ani"], "I respond to the invocation of the supplicant when he calls upon Me"),
    ("فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ", "فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون", ["falyastajeeboo lee walyu2minoo bee la3allahum yarshudoon", "falyastajibu li walyuminu bi la3allahum yarshudun"], "So let them respond to Me and believe in Me that they may be rightly guided"),
    ("قُلْ يَا عِبَادِيَ ٱلَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ ٱللَّهِ", "قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله", ["qul ya 3ibadiya alladheena asrafoo 3ala anfusihim la taqnatoo min ra7mati allah", "qul ya 3ibadiyal-ladhina asrafu 3ala anfusihim la taqnaTu min ra7matillah"], "Say, O My servants who have transgressed against themselves, despair not of the mercy of Allah"),
    ("إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا", "إن الله يغفر الذنوب جميعا", ["inna allaha yaghfiru al-dhunooba jamee3a", "innallaha ya8firudh-dhunuba jami3an"], "Indeed, Allah forgives all sins"),
    ("إِنَّهُ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", "إنه هو الغفور الرحيم", ["innahu huwa al-ghafooru al-ra7eem", "innahu huwal-ghafurur-rahim"], "Indeed, it is He who is the Forgiving, the Merciful"),
    ("وَٱلَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا", "والذين جاهدوا فينا لنهدينهم سبلنا", ["walladheena jahadoo feena lanahdiyannahum subulana", "walladhina jahadu fina lanahdiyannahum subulana"], "And those who strive for Us - We will surely guide them to Our ways"),
    ("وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ", "وإن الله لمع المحسنين", ["wa inna allaha lama3a al-mu7sineen", "wa innallaha lama3al-muhsinin"], "And indeed, Allah is with the doers of good"),
    ("مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً", "من عمل صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة", ["man 3amila sali7an min dhakarin aw untha wa huwa mu2minun falanu7yiyannahu 7ayatan tayyibah", "man 3amila Salihan min dhakarin aw untha wahuwa muminun falanu7yiyannahu 7ayatan Tayyibah"], "Whoever does righteousness, whether male or female, while a believer - We will surely cause him to live a good life"),
    ("وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ", "ولنجزينهم أجرهم بأحسن ما كانوا يعملون", ["wa lanajziyannahum ajrahum bi-a7sani ma kanoo ya3maloon", "walanajziyannahum ajrahum bi-a7sani ma kanu ya3malun"], "And We will surely give them their reward according to the best of what they used to do"),
    ("يَا أَيُّهَا ٱلَّذِينَ آمَنُوا ٱسْتَعِينُوا بِٱلصَّبْرِ وَٱلصَّلَاةِ", "يا أيها الذين آمنوا استعينوا بالصبر والصلاة", ["ya ayyuha alladheena amanoo ista3eenoo bil-sabri wal-salah", "ya ayyuhal-ladhina amanu ista3inu bis-Sabri was-salah"], "O you who have believed, seek help through patience and prayer"),
    ("يَا أَيُّهَا ٱلَّذِينَ آمَنُوا ٱذْكُرُوا ٱللَّهَ ذِكْرًا كَثِيرًا", "يا أيها الذين آمنوا اذكروا الله ذكرا كثيرا", ["ya ayyuha alladheena amanoo udhkuroo allaha dhikran katheera", "ya ayyuhal-ladhina amanu udhkurullaha dhikran kathiran"], "O you who have believed, remember Allah with much remembrance"),
    ("وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا", "وسبحوه بكرة وأصيلا", ["wa sabbi7oohu bukratan wa aseela", "wasabbihuhu bukratan wa aSila"], "And exalt Him morning and afternoon"),
    ("هُوَ ٱلَّذِي يُصَلِّي عَلَيْكُمْ وَمَلَائِكَتُهُ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَاتِ إِلَى ٱلنُّورِ", "هو الذي يصلي عليكم وملائكته ليخرجكم من الظلمات إلى النور", ["huwa alladhee yusallee 3alaykum wa mala2ikatuhu liyukhrijakum mina al-zulumati ila al-noor", "huwal-ladhi yuSalli 3alaykum wamala'ikatuhu liyu5rijakum minaz-zulumati ilan-nur"], "It is He who confers blessing upon you, and His angels ask for His forgiveness for you, that He may bring you out from darknesses into the light"),
    ("وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا", "وكان بالمؤمنين رحيما", ["wa kana bil-mu2mineena ra7eema", "wakana bil-muminina rahiman"], "And ever is He, to the believers, Merciful"),
    ("إِنَّ ٱللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى ٱلنَّبِيِّ", "إن الله وملائكته يصلون على النبي", ["inna allaha wa mala2ikatahu yusalloona 3ala al-nabiyy", "innallaha wamala'ikatahu yuSalluna 3alan-nabiyy"], "Indeed, Allah confers blessing upon the Prophet, and His angels ask Him to do so"),
    ("يَا أَيُّهَا ٱلَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا", "يا أيها الذين آمنوا صلوا عليه وسلموا تسليما", ["ya ayyuha alladheena amanoo salloo 3alayhi wa sallimoo tasleema", "ya ayyuhal-ladhina amanu Sallu 3alayhi wasallimu tasliman"], "O you who have believed, ask Allah to confer blessing upon him and ask Allah to grant him peace"),
    ("رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ", "ربنا تقبل منا إنك أنت السميع العليم", ["rabbana taqabbal minna innaka anta al-samee3u al-3aleem", "rabbana taqabbal minna innaka antas-sami3ul-3alim"], "Our Lord, accept this from us. Indeed You are the Hearing, the Knowing"),
    ("وَتُبْ عَلَيْنَا إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ", "وتب علينا إنك أنت التواب الرحيم", ["wa tub 3alayna innaka anta al-tawwabu al-ra7eem", "watub 3alayna innaka antat-tawwabur-rahim"], "And accept our repentance. Indeed, You are the Accepting of repentance, the Merciful"),
    ("رَبِّ ٱجْعَلْنِي مُقِيمَ ٱلصَّلَاةِ وَمِن ذُرِّيَّتِي", "رب اجعلني مقيم الصلاة ومن ذريتي", ["rabbi ij3alnee muqeema al-salati wa min dhurriyyatee", "rabbij-3alni muqimas-salati wamin dhurriyyati"], "My Lord, make me an establisher of prayer, and from my descendants"),
    ("رَبَّنَا وَتَقَبَّلْ دُعَاءِ", "ربنا وتقبل دعاء", ["rabbana wa taqabbal du3a2", "rabbana wataqabbal du3a'"], "Our Lord, and accept my supplication"),
    ("رَبَّنَا ٱغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ", "ربنا اغفر لي ولوالدي وللمؤمنين يوم يقوم الحساب", ["rabbana ighfir lee wa liwalidayya wa lil-mu2mineena yawma yaqoomu al-7isab", "rabbanagh-fir li waliwalidayya walil-muminina yawma yaqumul-7isab"], "Our Lord, forgive me and my parents and the believers the Day the account is established"),
    ("رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِٱلصَّالِحِينَ", "رب هب لي حكما وألحقني بالصالحين", ["rabbi hab lee 7ukman wa al7iqnee bil-sali7een", "rabbi hab li 7ukman wa al7iqni bis-salihin"], "My Lord, grant me wisdom and join me with the righteous"),
    ("وَٱجْعَل لِّي لِسَانَ صِدْقٍ فِي ٱلْآخِرِينَ", "واجعل لي لسان صدق في الآخرين", ["waj3al lee lisana sidqin fi al-akhireen", "waj3al li lisana Sidqin fil-a5irin"], "And grant me a reputation of honor among later generations"),
    ("وَٱجْعَلْنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ", "واجعلني من ورثة جنة النعيم", ["waj3alnee min warathati jannati al-na3eem", "waj3alni min warathati jannatin-na3im"], "And place me among the inheritors of the Garden of Pleasure"),
    ("يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ", "يوم لا ينفع مال ولا بنون", ["yawma la yanfa3u malun wa la banoon", "yawma la yanfa3u malun wala banun"], "The Day when neither wealth nor children will be of any benefit"),
    ("إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍ سَلِيمٍ", "إلا من أتى الله بقلب سليم", ["illa man ata allaha biqalbin saleem", "illa man atallaha biqalbin salim"], "Except he who comes to Allah with a sound heart"),
    ("هُوَ ٱللَّهُ ٱلَّذِي لَا إِلَٰهَ إِلَّا هُوَ عَالِمُ ٱلْغَيْبِ وَٱلشَّهَادَةِ", "هو الله الذي لا إله إلا هو عالم الغيب والشهادة", ["huwa allahu alladhee la ilaha illa huwa 3alimu al-ghaybi wal-shahadah", "huwallahul-ladhi la ilaha illa huwa 3alimul-8aybi wash-shahadah"], "He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed"),
    ("هُوَ ٱللَّهُ ٱلْخَالِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَاءُ ٱلْحُسْنَىٰ", "هو الله الخالق البارئ المصور له الأسماء الحسنى", ["huwa allahu al-khaliqu al-bari2u al-musawwiru lahu al-asma2u al-7usna", "huwallahul-5aliqul-bari'ul-muSawwiru lahul-asma'ul-7usna"], "He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names"),
    ("يُسَبِّحُ لَهُ مَا فِي ٱلسَّمَاوَاتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", "يسبح له ما في السماوات والأرض وهو العزيز الحكيم", ["yusabbi7u lahu ma fi al-samawati wal-ardi wa huwa al-3azeezu al-7akeem", "yusabbi7u lahu ma fis-samawati wal-ardi wahuwal-3azizul-7akim"], "Whatever is in the heavens and earth exalts Him, and He is the Exalted in Might, the Wise"),
])
